    IAM database authentication replaces long-lived cluster passwords with
    short-lived tokens tied to an IAM principal.
  RATIONALE

  desc 'check', <<~CHECK
    Checkov looks for: aws_rds_cluster: iam_database_authentication_enabled
    is True
  CHECK

  desc 'fix', <<~'FIX'
    Terraform — aws_rds_cluster:

      resource "aws_rds_cluster" "example" {
        iam_database_authentication_enabled = true
      }

    Out of band — aws_rds_cluster:

      aws rds modify-db-cluster --db-cluster-identifier <id> --enable-iam-database-authentication --apply-immediately
  FIX

  tag checkov_id:            'CKV_AWS_162'
  tag checkov_category:      'IAM'
  tag checkov_version:       '3.3.16'
  tag checkov_kind:          'value'
  tag tf_resources:          %w[aws_rds_cluster]
